export function extractBeaconCode(url: string): string {
    const matches = url.match(/\/([^\/?#]+)[^\/]*$/);
    return matches ? matches[1] : '';
}

interface RedeemBeaconSuccess {
    controllerUiUrl: string;
    gameId: number | undefined;
    gameplaySessionId: string;
    connectionSecret: string;
    connectionUrl: string;
    controllerUiParameters: { key: string; value: string }[];
}

export function buildControllerUrl(data: RedeemBeaconSuccess): string {
    const urlObj = new URL(data.controllerUiUrl);
    urlObj.searchParams.set('gameId', String(data.gameId));

    const hashParams = new URLSearchParams();
    for (const param of data.controllerUiParameters) {
        if (param.key !== 'gameId') hashParams.set(param.key, param.value || '');
    }
    hashParams.set('connectionSecret', data.connectionSecret);
    hashParams.set('connectionUrl', data.connectionUrl);
    hashParams.set('gameplaySessionId', data.gameplaySessionId);

    urlObj.hash = hashParams.toString();
    return urlObj.toString();
}
